package main

import (
	"bufio"
	"fmt"
	"os"
	"testing"
)

// Test compability of versions generated by older versions of hemlis

func TestV_0_1_0_CDC7BFD(t *testing.T) {
	testVersion("v.0.1.0-cdc7bfd", "AGE-SECRET-KEY-14CGCDKJYXUSFF2KZU2JKR9423U69PN3VZPMK8CAT73X7E9NQJM4SK9RZJF", t)
}

func testVersion(versionAndHash string, expectedSecret string, t *testing.T) {
	file, err := os.Open(fmt.Sprintf("test_data/%s.txt", versionAndHash))
	if err != nil {
		t.Fatal(err)
	}
	combinedSecret, err := readAndParseShares(bufio.NewScanner(file))
	if err != nil {
		t.Fatal(err)
	}
	if combinedSecret != expectedSecret {
		t.Errorf("Combined secret is not equal to orginal secret (%s)", versionAndHash)
		t.Errorf("Original secret: %v", expectedSecret)
		t.Errorf("Combined secret: %v", combinedSecret)
	}
}
